from typing import Union
from datetime import datetime

from taf.gnb.oam.coam.vdu.exceptions import WrongApiResponseStatus
from taf.internal.gnb.oam.coam.vdu.client.fh_licensed.v1.exceptions import ApiException

from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.components.antenna.antenna import Antenna
from taf.rfrl.procedures.resources.python.bts.components.cell.cloud_cell import CloudCell
from taf.rfrl.procedures.resources.python.bts.utils.timer import wait_for
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import RfScanUnexpectedResult
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug


class RfScan:
    """ Handles RF Scan functionality on BTS. """

    def __init__(self, api: Api, api_alias: str):
        """
        :param api: API used for handling RF Scan on BTS
        :param api_alias: name of opened API connection which this RF Scan should use
        """
        self._api = api
        self._api_alias = api_alias

    @pretty_log
    def run_rf_scan(self,
                    rmod: CloudRmod,
                    antenna: Union[Antenna, None],
                    cell: Union[CloudCell, None],
                    capture_type: str,
                    antenna_panel: Union[str, None],
                    timeout: int = 120,
                    expect_rejection: bool = False):
        """
        Starts RF Scan on given RMOD with provided RF Scan parameters and (by default) waits until it is successfully completed.
        :param rmod: RMOD on which RF Scan should be run
        :param antenna: antenna for which RF Scan should be run; if None provided then antenna will not be set
        :param cell: cell for which RF Scan should be run; if None provided then cell will not be set
        :param capture_type: capture type to be set before starting RF Scan;
                             one of the following: 'TX_COMBINED', 'TX_FEEDBACK', 'RX_COMBINED', 'RX_COMBINED_RAW', 'RX_CARRIER'
        :param antenna_panel: antenna panel to be set before starting RF Scan;
                              one of the following: 'Full_Array', 'Top_Array', 'Bottom_Array', 'Left_Array', 'Right_Array', 'All_Arrays';
                              if None provided then antenna panel will not be set
        :param timeout: time (in seconds) in which RF Scan should be successfully completed;
                        if 0 provided then there will be no waiting for RF Scan to complete;
                        defaults to 120
        :param expect_rejection: defines whether it should be expected that starting RF Scan will be rejected;
                                 defaults to False (rejection will not be expected)
        :raises RfScanUnexpectedResult: if running RF Scan is unsuccessful and rejection was not expected;
                                        if running RF Scan is successful and rejection was expected
        """
        expected_result_msg = 'and expecting rejection' if expect_rejection else f'with {timeout}s timeout for completion'
        log_info(f'Running RF Scan on {rmod.name} {expected_result_msg}', to_console=True)
        rmod_runtime_dist_name = rmod.runtime_dist_name
        antenna_runtime_dist_name = antenna.runtime_dist_name if antenna is not None else None
        cell_config_dist_name = cell.config_dist_name if cell is not None else None
        self._log_rf_scan_settings(ru_dn=rmod_runtime_dist_name,
                                   signal=capture_type,
                                   antenna=antenna_runtime_dist_name,
                                   antenna_carrier=cell_config_dist_name,
                                   antenna_panel=antenna_panel)

        operation_id = self._start_rf_scan(rmod_runtime_dist_name,
                                           capture_type,
                                           antenna_runtime_dist_name,
                                           cell_config_dist_name,
                                           antenna_panel,
                                           expect_rejection)

        if timeout and not expect_rejection:
            self._wait_for_rf_scan_to_complete(operation_id, timeout)

    @pretty_log
    def cancel_rf_scan(self, timeout: int = 120):
        """
        Cancels ongoing RF Scan.
        :param timeout: time (in seconds) in which RF scan should be successfully cancelled;
                if 0 provided then there will be no waiting for RF Scan to cancel;
                defaults to 120
        :raises RfScanUnexpectedResult: if cancelling RF Scan is unsuccessful
        """
        log_info(f'Cancelling RF Scan with {timeout}s timeout', to_console=True)
        operation_id = self._trigger_rf_scan_cancellation()

        if timeout:
            self._wait_for_rf_scan_to_cancel(operation_id, timeout)

    @pretty_log
    def download_rf_scan_result_file(self, download_dir_path: str, timeout: int = 60, expect_rejection: bool = False) -> Union[str, None]:
        """
        Downloads result file of completed RF Scan and stores it on local machine.
        :param download_dir_path: absolute path to directory where RF Scan result file should be stored; i.e. '/home/ute/results'
        :param timeout: timeout (in seconds) for downloading RF Scan result file; defaults to 60
        :param expect_rejection: defines whether it should be expected that downloading RF Scan result file will be rejected;
                                 defaults to False (rejection will not be expected)
        :returns: absolute path to RF Scan result file if downloading was successful, None otherwise
        :raises RfScanUnexpectedResult: if downloading RF Scan result file is unsuccessful and rejection was not expected;
                                        if downloading RF Scan result file is successful and rejection was expected
        """
        result_file_name = f'RFMonitoring_{datetime.now().isoformat()}.zip'
        result_file_path = f'{download_dir_path}/{result_file_name}'
        expected_result_msg = ' and expecting rejection' if expect_rejection else ''
        log_info(f'Downloading RF Scan result file to {result_file_path}{expected_result_msg}', to_console=True)
        result_msg = 'Result of downloading RF Scan result file is: {}'

        try:
            self._api.get_rf_scan_test_file(local_path=download_dir_path,
                                            local_file_name=result_file_name,
                                            timeout=timeout,
                                            vdu_connection=self._api_alias)
        except (ApiException, WrongApiResponseStatus) as api_error:
            if expect_rejection:
                log_debug(result_msg.format('rejected as expected'))
                return
            else:
                raise RfScanUnexpectedResult(result_msg.format(api_error))

        if expect_rejection:
            raise RfScanUnexpectedResult(result_msg.format('not rejected as expected'))

        log_debug(result_msg.format('downloaded'))
        return result_file_path

    @staticmethod
    def _log_rf_scan_settings(**settings):
        log_debug(f'RF Scan settings: {settings}')

    def _start_rf_scan(self,
                       rmod_runtime_dist_name: str,
                       capture_type: str,
                       antenna_runtime_dist_name: Union[str, None],
                       cell_config_dist_name: Union[str, None],
                       antenna_panel: Union[str, None],
                       expect_rejection: bool) -> Union[str, None]:
        result_msg = 'Result of starting RF Scan is: {}'

        try:
            api_response = self._api.start_rf_scan_test(ru_dn=rmod_runtime_dist_name,
                                                        signal=capture_type,
                                                        antenna=antenna_runtime_dist_name,
                                                        antenna_carrier=cell_config_dist_name,
                                                        antenna_panel=antenna_panel,
                                                        timeout=60,
                                                        vdu_connection=self._api_alias)
        except (ApiException, WrongApiResponseStatus) as api_error:
            if expect_rejection:
                log_debug(result_msg.format('rejected as expected'))
                return
            else:
                raise RfScanUnexpectedResult(result_msg.format(api_error))

        if expect_rejection:
            raise RfScanUnexpectedResult(result_msg.format('not rejected as expected'))

        if api_response['status'] != 'ongoing':
            raise RfScanUnexpectedResult(result_msg.format(api_response['status']))
        else:
            log_debug(result_msg.format(api_response['status']))

        return api_response['operation_id']

    def _wait_for_rf_scan_to_complete(self, operation_id: str, timeout: int):
        result_msg = 'Result of running RF Scan is: {}'
        completed = wait_for(expected_value='success',
                             abort_if='failure',
                             timeout=timeout,
                             raise_exc=False,
                             callback=self._get_status_of_rf_scan,
                             operation_id=operation_id)

        if not completed:
            raise RfScanUnexpectedResult(result_msg.format('not completed'))
        else:
            log_debug(result_msg.format('completed'))

    def _get_status_of_rf_scan(self, operation_id: str) -> str:
        api_response = self._api.get_rf_scan_test_operation_status(operation_id=operation_id,
                                                                   vdu_connection=self._api_alias)
        return api_response['status']

    def _trigger_rf_scan_cancellation(self) -> str:
        result_msg = 'Result of cancelling RF Scan is: {}'

        try:
            api_response = self._api.cancel_rf_scan_test_operation(timeout=60,
                                                                   vdu_connection=self._api_alias)
        except (ApiException, WrongApiResponseStatus) as api_error:
            raise RfScanUnexpectedResult(result_msg.format(api_error))

        if api_response['status'] != 'ongoing':
            raise RfScanUnexpectedResult(result_msg.format(api_response['status']))
        else:
            log_debug(result_msg.format(api_response['status']))

        return api_response['operation_id']

    def _wait_for_rf_scan_to_cancel(self, operation_id: str, timeout: int):
        result_msg = 'Result of cancelling RF Scan is: {}'
        cancelled = wait_for(expected_value='success',
                             abort_if='failure',
                             timeout=timeout,
                             raise_exc=False,
                             callback=self._get_status_of_rf_scan_cancellation,
                             operation_id=operation_id)

        if not cancelled:
            raise RfScanUnexpectedResult(result_msg.format('not cancelled'))
        else:
            log_debug(result_msg.format('cancelled'))

    def _get_status_of_rf_scan_cancellation(self, operation_id: str) -> str:
        api_response = self._api.get_rf_scan_test_cancellation_status(operation_id=operation_id,
                                                                      vdu_connection=self._api_alias)
        return api_response['status']
